import{_ as a,o,c as r,ae as n}from"./chunks/framework.YL6nI5ZP.js";const p=JSON.parse('{"title":"Construye tu Primera Red de Drenaje y Ejecuta una Corrida","description":"","frontmatter":{},"headers":[],"relativePath":"es/tutorials/02-tu-primera-red.md","filePath":"es/tutorials/02-tu-primera-red.md"}'),s={name:"es/tutorials/02-tu-primera-red.md"};function t(l,e,i,c,d,u){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="construye-tu-primera-red-de-drenaje-y-ejecuta-una-corrida" tabindex="-1">Construye tu Primera Red de Drenaje y Ejecuta una Corrida <a class="header-anchor" href="#construye-tu-primera-red-de-drenaje-y-ejecuta-una-corrida" aria-label="Permalink to &quot;Construye tu Primera Red de Drenaje y Ejecuta una Corrida&quot;">​</a></h1><p>En este tutorial construirás una pequeña red de aguas lluvias desde cero — nodos, enlaces y una subcuenca — configurarás sus parámetros, ejecutarás una corrida e inspeccionarás los resultados, todo a través de la interfaz de usuario de la aplicación.</p><h2 id="lo-que-construiras" tabindex="-1">Lo que construirás <a class="header-anchor" href="#lo-que-construiras" aria-label="Permalink to &quot;Lo que construirás&quot;">​</a></h2><p>Una red de drenaje pequeña: algunos nodos conectados por conductos y que terminan en un outfall, más una subcuenca que drena hacia la red. Usarás las herramientas de dibujo de la <strong>Paleta de Herramientas Izquierda</strong>, configurarás las propiedades de los elementos en el panel derecho y terminarás ejecutando la corrida y leyendo sus resultados.</p><h2 id="antes-de-empezar" tabindex="-1">Antes de empezar <a class="header-anchor" href="#antes-de-empezar" aria-label="Permalink to &quot;Antes de empezar&quot;">​</a></h2><p>Abre la aplicación: usa el sitio de producción en <a href="https://swmm6.is-local.org" target="_blank" rel="noreferrer">https://swmm6.is-local.org</a>, o sigue <a href="./../how-to/01-ejecutar-localmente">Cómo Ejecutar la Aplicación Localmente</a>. Si es tu primera vez, trabaja primero con <a href="./01-inicio-rapido">Primeros Pasos con Local SWMM</a>.</p><h2 id="paso-1-—-elige-tus-unidades" tabindex="-1">Paso 1 — Elige tus unidades <a class="header-anchor" href="#paso-1-—-elige-tus-unidades" aria-label="Permalink to &quot;Paso 1 — Elige tus unidades&quot;">​</a></h2><ol><li>Haz clic en el <strong>Ícono de Engranaje</strong> del mapa para abrir el menú <strong>Map Settings</strong>.</li><li>Bajo <strong>Units</strong>, selecciona <strong>SI</strong> (metros, milímetros, LPS) o <strong>US</strong> (pies, pulgadas, CFS).</li></ol><p>Nota para más adelante: si agregas una malla 2D a tu modelo, <strong>2D es solo SI</strong> — una corrida con una malla 2D presente mientras las unidades son US se rechaza con una advertencia.</p><h2 id="paso-2-—-agrega-nodos" tabindex="-1">Paso 2 — Agrega nodos <a class="header-anchor" href="#paso-2-—-agrega-nodos" aria-label="Permalink to &quot;Paso 2 — Agrega nodos&quot;">​</a></h2><ol><li>En la <strong>Paleta de Herramientas Izquierda</strong>, elige una <strong>herramienta de Nodo</strong> — <strong>Junction</strong>, <strong>Outfall</strong>, <strong>Storage</strong> o <strong>Divider</strong>.</li><li><strong>Haz clic en el mapa</strong> para colocar un nodo de ese tipo.</li></ol><p>Dos cosas a tener en cuenta:</p><ul><li>Cuando colocas un nodo, la aplicación <strong>extrae automáticamente la elevación del terreno desde el DEM de Mapbox</strong>. Puedes hacer clic en <strong>Sample DEM Elevation</strong> en el panel <strong>Properties</strong> para actualizar la elevación de un nodo seleccionado.</li><li>Cada elemento recibe un ID generado automáticamente: los nodos usan los prefijos <code>J</code> (junction), <code>O</code> (outfall), <code>ST</code> (storage), <code>D</code> (divider), <code>RG</code> (rain gage); los enlaces usan <code>C</code>, <code>P</code>, <code>W</code>, <code>OR</code>, <code>OL</code>; las subcuencas usan <code>S</code>.</li></ul><p>Debes colocar al menos <strong>un outfall</strong>: la aplicación se niega a ejecutar un modelo sin nodos o sin <code>OUTFALL</code>.</p><h2 id="paso-3-—-conecta-los-nodos-con-enlaces" tabindex="-1">Paso 3 — Conecta los nodos con enlaces <a class="header-anchor" href="#paso-3-—-conecta-los-nodos-con-enlaces" aria-label="Permalink to &quot;Paso 3 — Conecta los nodos con enlaces&quot;">​</a></h2><ol><li>En la <strong>Paleta de Herramientas Izquierda</strong>, elige la herramienta <strong>Conduit</strong> (o <strong>Pump</strong>, <strong>Weir</strong> u <strong>Orifice</strong> para otros tipos de enlace).</li><li><strong>Haz clic en un nodo de inicio y en un nodo de fin</strong> para dibujar el enlace.</li></ol><p>La longitud del conducto se calcula automáticamente. Los conductos nuevos vienen con valores predeterminados sensatos: <code>roughness:0.013</code>, <code>autoLength:true</code>, <code>xShape:&#39;CIRCULAR&#39;</code>, <code>geom1:1.0</code>, <code>barrels:1</code>.</p><h2 id="paso-4-—-agrega-una-subcuenca-y-un-pluviometro" tabindex="-1">Paso 4 — Agrega una subcuenca y un pluviómetro <a class="header-anchor" href="#paso-4-—-agrega-una-subcuenca-y-un-pluviometro" aria-label="Permalink to &quot;Paso 4 — Agrega una subcuenca y un pluviómetro&quot;">​</a></h2><ol><li>Elige la herramienta <strong>Subcatchment</strong> y luego <strong>haz clic en varios puntos del mapa</strong> para dibujar el polígono de la subcuenca. <strong>Haz doble clic</strong> para cerrar el polígono.</li><li>Elige la herramienta <strong>Rain Gage</strong> y <strong>haz clic en el mapa</strong> para agregar un objeto de pluviómetro.</li></ol><p>Cuando cierras una subcuenca, su área se calcula automáticamente (en ha/ac) y <strong>el nodo hidráulico más cercano se elige como su punto de salida</strong>.</p><p>Consejo: con la <strong>Select Tool</strong> (<code>Esc</code>) puedes hacer clic en los elementos para seleccionarlos y <strong>arrastrar nodos para mover su posición</strong>. Deshaz con <code>Ctrl+Z</code>, rehaz con <code>Ctrl+Shift+Z</code>; <code>Del</code>/<code>Backspace</code> elimina el elemento seleccionado.</p><h2 id="paso-5-—-configura-los-parametros" tabindex="-1">Paso 5 — Configura los parámetros <a class="header-anchor" href="#paso-5-—-configura-los-parametros" aria-label="Permalink to &quot;Paso 5 — Configura los parámetros&quot;">​</a></h2><ol><li>Haz clic en un elemento con la <strong>Select Tool</strong> para mostrar sus propiedades en la pestaña <strong>Properties</strong> del panel derecho.</li><li>Edita los valores que necesites.</li><li>Para opciones de todo el solver, haz clic en <strong>Options</strong> en la <strong>Barra de Herramientas Superior</strong>: <ul><li><strong>Node Continuity</strong>: selecciona la formulación <strong>Legacy (Default)</strong> o <strong>SEMI_IMPLICIT (Enhanced)</strong>.</li><li><strong>Anderson Acceleration</strong>: selecciona <strong>Yes</strong> para acelerar la convergencia de la iteración de Picard en transiciones de sobrenivel rígidas.</li><li><strong>Physics-Based RDII Abstraction Recovery</strong>: ingresa los parámetros de recuperación (<code>k0</code>, <code>kT</code>, <code>Tref</code>) para la recuperación de la infiltración de precipitación.</li></ul></li></ol><h2 id="paso-6-—-guarda-tu-trabajo" tabindex="-1">Paso 6 — Guarda tu trabajo <a class="header-anchor" href="#paso-6-—-guarda-tu-trabajo" aria-label="Permalink to &quot;Paso 6 — Guarda tu trabajo&quot;">​</a></h2><ul><li><strong>Save</strong>: haz clic en <strong>Save</strong> para exportar tu modelo a un archivo <code>.json</code> (un archivo de proyecto <code>*.oswmm.json</code> con impresión bonita) o guardarlo en el almacenamiento del navegador.</li><li>La aplicación también guarda automáticamente por ti: cada cambio se almacena en el almacenamiento del navegador después de un breve debounce (clave de localStorage <code>openswmm3d.project</code>, con respaldo IndexedDB) y se restaura en la siguiente carga.</li><li><strong>Load / Import</strong> (desde el menú desplegable <strong>Open Model ▾</strong>) te permite reabrir archivos de proyecto, restaurar desde el almacenamiento del navegador o importar archivos <code>.inp</code>, shapefile (<code>.zip</code>) y <code>.dxf</code>.</li></ul><h2 id="paso-7-—-ejecuta-la-corrida" tabindex="-1">Paso 7 — Ejecuta la corrida <a class="header-anchor" href="#paso-7-—-ejecuta-la-corrida" aria-label="Permalink to &quot;Paso 7 — Ejecuta la corrida&quot;">​</a></h2><ol><li>Asegúrate de que tu red contenga <strong>al menos un nodo outfall y conductos conectados</strong>.</li><li>Haz clic en <strong>Run</strong> en la <strong>Barra de Herramientas Superior</strong>.</li><li>Supervisa el progreso en la ventana <strong>Run Status</strong> (porcentaje de progreso y tiempo simulado en <code>Days</code> y <code>Hrs:Min</code>). Puedes <strong>Stop</strong> la corrida o <strong>Minimize</strong> a una insignia flotante en cualquier momento.</li></ol><p>Si la corrida aborta de inmediato con una advertencia, las causas son: sin nodos, sin <code>OUTFALL</code>, o <strong>unidades US con una malla 2D</strong> (2D es solo SI).</p><h2 id="paso-8-—-inspecciona-los-resultados" tabindex="-1">Paso 8 — Inspecciona los resultados <a class="header-anchor" href="#paso-8-—-inspecciona-los-resultados" aria-label="Permalink to &quot;Paso 8 — Inspecciona los resultados&quot;">​</a></h2><ul><li><strong>Panel de Control Deslizante de Tiempo</strong>: usa la barra de animación inferior para reproducir, pausar, cambiar la velocidad o arrastrar hasta un paso de tiempo específico. Los colores del mapa se actualizan por paso.</li><li><strong>Pestaña Properties</strong>: haz clic en cualquier nodo o enlace para ver sus propiedades geométricas y <strong>los caudales calculados</strong>.</li><li><strong>Pestaña Results</strong>: selecciona categorías de resultados para ver tablas resumen — Node Depths, Node Inflows, Link Flows y Subcatchment Runoff.</li><li><strong>Perfil de Elevación de Agua</strong>: selecciona nodos conectados y pulsa <strong>Profile</strong> para ver un gráfico de perfil hidráulico interactivo.</li></ul><h2 id="lo-que-deberias-ver-al-final" tabindex="-1">Lo que deberías ver al final <a class="header-anchor" href="#lo-que-deberias-ver-al-final" aria-label="Permalink to &quot;Lo que deberías ver al final&quot;">​</a></h2><ul><li>Una red con nodos (incluido un outfall), enlaces y una subcuenca, cada uno con un ID y propiedades editables.</li><li>Una corrida completada con las pestañas <strong>Results</strong> y <strong>Report</strong> pobladas en el panel derecho.</li><li>Una reproducción animada de la simulación en el mapa mediante el control deslizante de tiempo.</li></ul><h2 id="siguientes-pasos" tabindex="-1">Siguientes pasos <a class="header-anchor" href="#siguientes-pasos" aria-label="Permalink to &quot;Siguientes pasos&quot;">​</a></h2><ul><li><strong>Agrega una malla 2D</strong> para el tránsito superficial sobre el terreno: usa el botón <strong>Mesh2D</strong> o el menú <strong>Data</strong> (<strong>2D Mesh</strong>) para abrir el diálogo de malla, un modal de 3 pestañas (<strong>Sources / Quality / Hydraulics</strong>) que genera la malla de superficie. Recuerda que 2D requiere unidades SI.</li><li>Aprende más sobre el modelo detrás de la UI en las secciones de referencia de esta documentación.</li></ul>',34)])])}const m=a(s,[["render",t]]);export{p as __pageData,m as default};
